## Complex: callbacks and async to C, Python and JavaScript

```jet
// crawler.jet
use http: core.http.client
use net: core.net

#Export(c, py, js)
Page: struct {
    url: String
    status: Int
    bytes: Int
}

// A call-scoped callback: hosts may pass any function or closure.
#Export(c, py, js)
crawl: fn(start: String, limit: Int, on_page: fn(Page)) -> Int !net.HTTPError {
    seen := 0
    queue := [start]
    loop {
        if seen >= limit || queue.len() == 0 -> break
        url: queue.pop_front() ?? break
        resp: http.get(url)
        on_page(Page{url: url, status: resp.status, bytes: resp.body.len()})
        loop link in resp.links() -> queue.push(link)
        seen += 1
    }
    seen
}

// A waiting function: completion callback plus cancel handle in C, async def in Python, Promise in JS.
#Export(c, py, js)
fetch_title: fn(url: String) -> String !net.HTTPError {
    http.get(url).html().title() ?? "(untitled)"
}
```

