## Complex: a web component written in Jet, used from JS, using JS

What it shows: exporting a Jet type as a custom element (D-FFI-EXPORT3, host `js`), JS events delivered to Jet
callbacks, a JS library (`marked`) called from Jet, and a JS caller awaiting a Jet waiting function.

```jet
package: {
    name: "md_editor"
    deps: {
        marked: js@"marked@14.1"
        purify: js@"dompurify@3.2"
    }
    targets: [wasm32-web]
}

use md: js.marked
use purify: js.dompurify
use web: core.web

#Export(js)
MarkdownEditor: struct {
    area: web.TextArea
    preview: web.Element
}

render_into: fn(preview: web.Element, text: String) {
    html: md.parse(text, md.Options{gfm: true})                     // marked returns a string
    preview.set_inner_html(purify.sanitize(html))                     // never insert unsanitized HTML
}

#Export(js)
impl MarkdownEditor {
    mount: fn(root: web.Element) -> MarkdownEditor {
        area: web.document.create<web.TextArea>("textarea")
        preview: web.document.create<web.Element>("div")
        root.append(area)
        root.append(preview)
        area.on_input((e) -> render_into(preview, e.target.value))     // retained; captures a JS handle, which is sendable
        MarkdownEditor{area: area, preview: preview}
    }

    render: fn(self, text: String) {
        self.area.set_value(text)                                       // a method on the JS handle
        render_into(self.preview, text)
    }

    // A waiting Jet function becomes a Promise for JS callers.
    save: fn(self, url: String) -> Int !web.FetchError {
        web.fetch(url, method: .Post, body: self.area.value).status
    }
}
```

```js
// index.js, written by hand in the web app
import { MarkdownEditor } from "./md_editor.js";       // glue written by jsbind's export
const ed = MarkdownEditor.mount(document.querySelector("#editor"));
ed.render("# Hello\n\nFrom **Jet**");
const status = await ed.save("/api/doc");              // Promise<number>; FetchError arrives as a thrown Error
```

```ts
// md_editor.d.ts, written by jsbind
export class MarkdownEditor {
    static mount(root: Element): MarkdownEditor;
    render(text: string): void;
    save(url: string): Promise<number>;
    free(): void;                                        // also released by FinalizationRegistry
}
```

A closed native binary in `deps` would be refused for this target with E3238, naming the library and offering the
server-side form.

