// The binder behind `use c.…` is a Jet package (cbind) implementing Language.
use core.ffi

pub struct C {
    lib: String
    headers: [String]
}

impl C.Language {
    root :: "c"
    fn expand(self, target: Target) !ffi.BindError {
        clang :: ffi.tool("clang", "19.1.7")
        ast :: clang.run(["-Xclang", "-ast-dump=json", ...self.headers], inputs: self.headers)
        loop f in read_api(ast).functions {
            if decide(f, derive_facts(f)) == {
                .Plain(shape) -> emit_plain(f, shape)
                .Guarded(shape, guards) -> emit_guarded(f, shape, guards)
                .Refused(why) -> emit_refused(f, why)
            }
        }
    }
}

// A user's own language, published on Jetpack as odinbind (root "odin").
pub struct Odin {
    source: String
}

impl Odin.Language {
    root :: "odin"
    fn expand(self, target: Target) !ffi.BindError {
        odin :: ffi.tool("odin", "dev-2026-10")
        doc :: odin.run(["doc", self.source, "-doc-format:json"], inputs: [self.source])
        evidence :: ffi.Evidence.from_tool(odin, self.source)
        loop p in json.decode<[OdinProc]>(doc) {
            pub fn #{p.name}(...#{jet_params(p)}) -> #{jet_type(p.result)} {
                ffi.extern<#{native_sig(p)}>(#{p.link_name}, evidence).call(...#{jet_args(p)})
            }
        }
    }
}

