use core.ffi

#ffi.Facts(ResultOwned(sqlite3_close), Effects([FS]))
pub struct Database { h: ffi.Handle<Sqlite3> }

impl Database.Close {
    fn close(^self) { ffi.extern<fn(ffi.Handle<Sqlite3>) -> I32>("sqlite3_close", PACK).call(self.h) }
}

pub fn open(path: String) -> Database !SqliteError {
    out := ffi.Out<ffi.Handle<Sqlite3>>{}
    rc :: ffi.extern<fn(ffi.CStr, ffi.Out<ffi.Handle<Sqlite3>>, I32, ?ffi.CStr) -> I32>(
        "sqlite3_open_v2", PACK).call(ffi.cstr(&path), &out, OPEN_RW, .None)
    if rc != 0 -> return Err(SqliteError.from(rc))
    Ok(Database{h: out.take()})
}

impl Database {
    // Borrowed text owned by the handle: a view, valid while &self is held.
    pub fn errmsg(&self) -> StringView {
        p :: ffi.extern<fn(ffi.Handle<Sqlite3>) -> ffi.CText>("sqlite3_errmsg", PACK).call(self.h)
        ffi.view_text(ffi.guard.utf8(p), from: self, evidence: PACK)
    }
}

