use rust.local_parser as parser
use py.yaml as yaml
use core.files as fs

fn run() {
    rules :: yaml.safe_load(fs.read("rules.yaml"))
    data :: zstd.decompress(fs.read_bytes("logs.zst"))
    loop line in parser.lines(data) {
        if re.Regex.new(rules["pattern"].text()).is_match(line) -> print(line)
    }
}

