// package audit
struct Audit {
    impl Effect {
        parent :: Log            // Audit is a kind of Log
    }
}

pub fn record(event: String) -[Audit]> {
    log.info(event)
}

// another package
fn ship() -[Log]> {              // allowing Log allows audit.Audit
    audit.record("shipped")
}

fn strict() -[audit.Audit]> {    // or allow only the audit part
    audit.record("checked")
}

// package audit
#FX(Log)                         // may do at most what Log does
struct Audit {
    impl Effect {}
}

pub fn record(event: String) -[Audit]> {
    log.info(event)
}

// another package
fn ship() -[Log, audit.Audit]> { // Log alone no longer covers it
    audit.record("shipped")
}

// Core gives Log a constant field
struct Log {
    topic: String{""}
    impl Effect {}
}

// package audit: no type of its own
pub fn record(event: String) -[Log{topic: "audit"}]> {
    log.info(event)
}

// another package
fn ship() -[Log]> {              // allowing Log covers every topic
    audit.record("shipped")
}

