// proposed (A), not built. Every named thing is a constant bound with ::, as D-DECL-BINDING1=B ratified.
// The body of a package or module holds its metadata fields first, then its bindings.
// package.jet and module.jet are bodies with implicit braces; any other file wraps the body in braces.
// Three files plus the built-in types; run.jet prints the lines in its comments.

// ===== core.meta: the two built-in metadata types =====
Module :: struct {
    name: String                      // set by the compiler: the module's name
    file: String                      // set by the compiler: its file, from the package root
    doc: String                       // set by the compiler: the /// comment above it, or ""
    package: Package                  // set by the compiler: the package that owns it
    maturity: Maturity{.Tested}       // yours to set: .Experimental, .Tested or .Hardened
    category: String{""}              // yours to set: a group name for docs and tools
    deprecated: Deprecated{none}      // yours to set: uses from other modules warn
}

Package :: struct {                   // every package.jet field, with today's defaults
    name: String
    version: String{"0.0.0"}
    description: String{none}
    license: String{none}
    authors: [String]{[String]{}}     // new: the one field package.jet lacks today
    deps: [String: DepSpec]{[String: DepSpec]{}}
    // edition, jet, repository, runtime, allocator, outputs, defaults, configs,
    // authority and policy keep today's types and defaults.
}

// ===== package.jet: the whole file is the package's body, so its braces are implicit =====
name: "shop"
version: "0.3.0"
license: "MIT"
authors: ["Mia Chen"]
deps: {
    json: "1.4.2",
}

// ===== pricing/module.jet: the whole file is the module's body, so its braces are implicit =====
/// Price rules for the shop.
category: "billing"                   // opt in: every field not written keeps its default

total :: fn(text: String) -> Int { text.len() }

// ===== run.jet: any other file wraps a module's body in braces =====
use json
use core.meta.[Module]                // describe names the type, so it imports it
module pricing                        // loads pricing/module.jet

/// Old discount rules, kept for one release.
discount :: module {
    category: "billing"               // metadata fields come first, inside the braces
    maturity: .Experimental
    deprecated: Deprecated{since: "0.3.0", use: "pricing"}

    total :: fn(text: String) -> Int { text.len() - 1 }
}

describe :: fn(m: Module) -> String { "{m.name} ({m.category}, {m.maturity})" }

run :: fn() {
    print(pricing.total("abc"))           // 3
    print(pricing.category)               // billing
    print(pricing.doc)                    // Price rules for the shop.
    print(pricing.file)                   // pricing/module.jet
    print(discount.file)                  // run.jet
    print(describe(pricing))              // pricing (billing, Tested): a module is a Module value
    print(describe(discount))             // discount (billing, Experimental)
    print(discount.total("abc"))          // 2, and the build warns: discount is deprecated since 0.3.0; use pricing
    print(#package.version)               // 0.3.0: the package this line is in
    print(#package.authors)               // [Mia Chen]
    print(json.package.version)           // 1.4.2: a dependency's version
}

