    t :: ^d.front
    d.front = ^d.back
    d.back = ^t
}

enum Conn {
    Idle
    Open(buf: [U8])
}

// next may stop (it is not marked -[!Panic]>).
fn next(c: ^Conn) -> Conn {
    if ^c == {
        .Idle -> .Open(buf: [U8]{})
        .Open(buf) -> .Idle
    }
}

struct Client {
    conn: Conn
}

impl Client {
    fn step(&self) {
        // The place holds a stand-in while next runs.
        old :: mem.replace(&self.conn, .Idle)
        self.conn = next(^old)
        // By hand, self.conn = next(^self.conn) is refused:
        // a stop inside next would leave the caller an empty place.
    }
}

// The caller's side is the same for both forms.
fn run() {
    d := Deque{front: [1], back: [2, 3]}
    flip(&d)
    flip_by_hand(&d)
    print(d.front.len())
    s := Stack{head: Val([1, 2])}
    got :: &s.pop_all()
    print((got ?? [Int]{}).len())
    rows := [[1], [2, 3]]
    was :: mem.replace(&rows[1], [4, 5, 6])
    print(was.len())
    // Two positions picked at run time go to the list's own swap.
    &rows.swap(0, 1)
    c := Client{conn: .Idle}
    &c.step()
}

