use process: core.process

// Both values are built while compiling and read while running.
COUNT: 50000000

// Steps the Collatz walk takes from each number down to 1, one byte each
// (the count wraps at 256). A walk stops early at a smaller, known number.
collatz_steps: fn(count: Int) -> [U8] {
    known := [Int]{0, 0}
    table := [U8]{U8{0}, U8{0}}
    loop n in 2..<count {
        steps := 0
        x := n
        loop {
            if x < n -> break
            x = if x % 2 == 0 -> x /% 2 else -> 3 * x + 1
            steps += 1
        }
        total: steps + known[x]
        known.push(total)
        table.push(U8.from_int(total % 256) ?? U8{0})
    }
    table
}

