        // A reflected type is a TypeId and passes as is.
        fields.push(CompilerField{name: name, type: field.type.copy()})
    }
    // add_struct returns Shape's TypeId for later fields.
    shape: meta.add_struct("Shape", fields, scope: "shape")
    b.default(app)
}

