use {
    browser: core.web.browser
    core.web.browser.[BrowserError]
}

// The paused 1-based generated line, and whether a scriptParsed named app.js.map.
live: fn(port: Int, line: Int) -> (paused_line: Int, saw_map: Bool) BrowserError! {
    b: browser.launch("chromium")
    page: b.context().page()
    // New: a CDP handle whose commands and events belong to this page only.
    cdp: page.protocol("cdp")
    cdp.subscribe("Debugger.scriptParsed")
    cdp.subscribe("Debugger.paused")
    _: cdp.send("Debugger.enable", "{{}}")
    _: cdp.send("Debugger.setBreakpointByUrl", "{{\"urlRegex\":\".*app\\\\.js(\\\\?.*)?$\",\"lineNumber\":{line},\"columnNumber\":0}}")
    // CDP navigation returns at once; page.goto would wait for a load the pause blocks.
    _: cdp.send("Page.navigate", "{{\"url\":\"http://127.0.0.1:{port}/click/\"}}")
    // New: browser.fact_hash is the hash events already use for url_hash.
    map: browser.fact_hash("app.js.map")
    names: [browser.fact_hash("render"), browser.fact_hash("jet_main"), browser.fact_hash("")]
    saw_map := false
    loop {
        event: cdp.next_event(browser.timeout(20000))
        // New: named facts read from the event; nothing else of it is kept.
        if event.kind() == "Debugger.scriptParsed" && event.source_map_url_hash() == map -> saw_map = true
        if event.kind() != "Debugger.paused" -> next
        if !names.contains(event.frame_function_hash()) -> return Err(BrowserError{kind: "protocol"})
