#Rename(.Camel)
ScriptParsed: struct { source_map_url: String? }
ScriptMessage: struct { params: ScriptParsed }

// Sends one command and returns its reply; events that arrive first are kept in order.
command: fn(conn: WsConn, call: Int, session: String, method: String, params: String, events: &[String]) -> String (WsError | EncodingError | [FieldError])! {
    target: if session == "" -> "" else -> ",\"sessionId\":\"{session}\""
    conn.send_text("{{\"id\":{call},\"method\":\"{method}\",\"params\":{params}{target}}}")
    loop {
        text: conn.recv().text() ?? next
        if (json.parse(text).decode<Envelope>().id ?? -1) == call -> return Ok(text)
        events.push(text)
    }
}

// The paused 1-based generated line, and whether a scriptParsed named app.js.map.
live: fn(port: Int, line: Int) -> (paused_line: Int, saw_map: Bool) (BrowserError | IOError | WsError | EncodingError | [FieldError])! {
    // The pinned Chromium from .jet/lock, launched by the tool itself.
    chromium: browser.locked("chromium")
    profile: files.temp_dir("jet-cdp-")
    child := process.cmd([String]{chromium.binary(), "--headless=new", "--remote-debugging-port=0", "--user-data-dir={profile}", "about:blank"}).spawn()
    loop !files.exists("{profile}/DevToolsActivePort") -> time.sleep(time.duration_ms(50))
    listening: files.read("{profile}/DevToolsActivePort").lines()
    conn: ws.connect("ws://127.0.0.1:{listening[0]}{listening[1]}")
    events := [String]{}
    created: json.parse(command(conn, 1, "", "Target.createTarget", "{{\"url\":\"about:blank\"}}", events)).decode<Created>()
    attached: json.parse(command(conn, 2, "", "Target.attachToTarget", "{{\"targetId\":\"{created.result.target_id}\",\"flatten\":true}}", events)).decode<Attached>()
    page: attached.result.session_id
    _: command(conn, 3, page, "Debugger.enable", "{{}}", events)
    _: command(conn, 4, page, "Debugger.setBreakpointByUrl", "{{\"urlRegex\":\".*app\\\\.js(\\\\?.*)?$\",\"lineNumber\":{line},\"columnNumber\":0}}", events)
    _: command(conn, 5, page, "Page.navigate", "{{\"url\":\"http://127.0.0.1:{port}/click/\"}}", events)
    saw_map := false
    at := 0
    loop {
        // recv has no timeout: a hung browser hangs here.
        if at == events.len() -> events.push(conn.recv().text() ?? "{{}}")
        text: events[at].copy()
        at += 1
        method: json.parse(text).decode<Envelope>().method ?? ""
        if method == "Debugger.scriptParsed" && (json.parse(text).decode<ScriptMessage>().params.source_map_url ?? "") == "app.js.map" -> saw_map = true
        if method != "Debugger.paused" -> next
        top: json.parse(text).decode<PausedMessage>().params.call_frames[0]
        if !["render", "jet_main", ""].contains(top.function_name) -> return Err(BrowserError{kind: "protocol"})
        _: command(conn, 6, page, "Debugger.resume", "{{}}", events)
        child.kill().drop("the check is done")
        return Ok((paused_line: top.location.line_number + 1, saw_map: saw_map))
    }
}

