// Swift: cancelling the parent task cancels every child task in its task group.
let job = Task {
    await withTaskGroup(of: Void.self) { group in
        group.addTask { await fetch("a") }
        group.addTask { await fetch("b") }
    }
}
job.cancel()   // both fetches see the cancel at their next await

options.code:
use time: core.time

fetch_page: fn(name: String) {
    time.sleep(3000ms)   // stands in for a slow network read
    print("fetched {name}")
}

fetch_all: fn() {
    task.group pages {
        task fetch_page("a")
        task fetch_page("b")
    }
    print("all pages fetched")
}

run: fn() {
    job: task fetch_all()
    time.sleep(100ms)
    job.cancel()
    job.join() ?? print("job stopped")
}
// A prints: job stopped
// Both fetches stop at their sleep and clean up; nothing else prints.

